declaration:
interface SignalD {
  /**
   * 信号源名称
   */
  name: string;
  /**
   * 信号源Id
   */
  sourceId: number;
  /**
   * 卡插槽Id
   */
  slotId: number;
  /**
   * 分辨率宽
   */
  width: number;
  /**
   * 分辨率高
   */
  height: number;
  /**
   * 刷新率
   */
  refreshRate: number;
  /**
   * 状态，1表示离线，2表示在线
   */
  status: number;
  /**
   * 信号源接口类型
   */
  interfaceType: number;
  /**
   * 拼接视频画面的大块索引
   */
  videoIndex?: number;
  /**
   * 信号源截取列表
   */
  crops?: CropsD[];
  /**
   * PIMP-大屏信号源列表-信号源ID
   */
  signalId?: number;
  /**
   * 自定义字段
   */
  groupId?: number;
}
